/** Real SQL, with read/write tripwires and changes at the boundary of an aggregate read. */
class AnalyticsReadPDO extends PDO
{
    public bool $readGuard=false,$failRead=false,$failClock=false;public int $writeAttempts=0,$factReads=0;public mixed $onFactRead=null;
    private function inspect(string $sql): void
    {
        if($this->readGuard&&!preg_match('/^\s*(SELECT|PRAGMA)\b/i',$sql)){$this->writeAttempts++;throw new RuntimeException('Analytics attempted a write.');}
        if($this->failClock&&str_contains($sql,' AS as_of'))throw new PDOException('SECRET clock failure');
        if(!preg_match('/\b(?:FROM|JOIN)\s+(?:vp3_radar_sessions|vp3_radar_events|profile_events)\b/i',$sql))return;
        $this->factReads++;if($this->failRead)throw new PDOException('SECRET query failure /private/path');
        if($this->onFactRead){$callback=$this->onFactRead;$this->onFactRead=null;$callback();}
    }
    public function exec(string $sql): int|false{$this->inspect($sql);return parent::exec($sql);}
    public function prepare(string $sql,array $options=[]): PDOStatement|false{$this->inspect($sql);return parent::prepare($sql,$options);}
    public function query(string $sql,?int $mode=null,mixed ...$args): PDOStatement|false{$this->inspect($sql);return $mode===null?parent::query($sql):parent::query($sql,$mode,...$args);}
}
